import { defineActions } from "@/components/surface/catalog"
import {
  DECIDED,
  QUEUE,
  RULES,
  SINCE,
  type QueueItem,
} from "@/examples/davinci2/data"

// The host side of davinci on surfaces: what the factory offers and what
// the agent may read. Two contracts the agent can't bend:
//
// - Actions: the events the factory accepts, and what each one is. The
//   renderer derives "Irreversible", Undo and the mandatory confirmation
//   from here; whatever the agent marks is ignored. In the real factory each
//   name maps to the chat action contract (receipts, idempotency).
// - Facts: counts, rates and times come from the factory's data, bound by
//   path. The agent writes the why, never the how much.

export const factoryActions = defineActions({
  approve: {
    reversible: true,
    describe: "Approves the plan; build starts now",
  },
  choose: { reversible: true, describe: "Answers with the chosen option" },
  promote: {
    reversible: true,
    describe: "Promotes to main; ships with the next wave",
  },
  adjust: { reversible: true, describe: "Sends it back with a note" },
  // A migration in the diff can't be taken back once integrated.
  integrate: {
    reversible: false,
    describe: "Queues the change for integration",
  },
  return: { reversible: true, describe: "Returns the change with a note" },
  revert: {
    reversible: true,
    describe: "Reverts the culprit through full gates",
  },
  keep: { reversible: true, describe: "Keeps the release and investigates" },
  make_rule: {
    reversible: true,
    describe: "Turns repeated agreement into a rule",
  },
  toggle_rule: { reversible: true },
  // Some of davinci's decisions can be taken back, some can't (a re-woken
  // operator, a retried run): the factory knows which, per decision.
  undo: {
    reversible: (context) =>
      DECIDED.find((d) => d.id === context.id)?.reversible ?? false,
    describe: "Undoes a decision davinci made for you",
  },
  open_diff: {},
  open_preview: {},
})

export type FactoryAction = keyof typeof factoryActions

/** The data model the agent binds to: the factory's own numbers. */
export function factoryData(answered: Record<string, string>) {
  const open = QUEUE.filter((q) => !answered[q.id])
  const undone = (id: string) => Boolean(answered[`undo:${id}`])
  const decided = DECIDED.filter((d) => !undone(d.id))
  return {
    summary: {
      title: open.length
        ? `${open.length} decisions need you`
        : "Nothing needs you",
      since: `Since 21:00: ${SINCE.calm.shipped} shipped, ${SINCE.calm.stuck} stuck, ${decided.length} decided for you.`,
    },
    items: Object.fromEntries(QUEUE.map((q) => [q.id, item(q)])),
    answered: QUEUE.filter((q) => answered[q.id]).map((q) => ({
      id: q.id,
      what: `${answered[q.id]} · ${q.title}`,
      project: q.project,
    })),
    decided: DECIDED.map((d) => ({
      id: d.id,
      time: d.time,
      subject: d.project,
      what: d.what,
      why: d.why,
      rule: RULES.find((r) => r.id === d.rule)?.text,
      undone: undone(d.id),
    })),
    rules: RULES.map((r) => ({
      id: r.id,
      text: r.text,
      category: r.category,
      applied: r.applied,
      on: true,
    })),
  }
}

function item(q: QueueItem) {
  return {
    eyebrow: `${q.project} · ${q.category}`,
    title: q.title,
    context: q.context,
    consequence: q.consequence,
    options: q.options,
    pick: q.pick,
    agreement: q.agreement && { ...q.agreement, category: q.category },
  }
}

export { QUEUE }

import type { ComponentNode, SurfaceMessage } from "@/components/surface/types"
import { UIA_CATALOG_ID } from "@/components/catalog"
import type { QueueItem, Urgency } from "@/examples/davinci2/data"

// What davinci's agent sends to show the inbox: A2UI messages against the
// uia catalog, written only from patterns (DecisionCard, ActivityItem,
// Policy) so the screen holds the hand-made level. Every fact
// is a binding into the factory's data (`/items/<id>/…`, `/summary/…`); the
// actions are the factory's own event names.
//
// This function stands in for the model: same input, same output, so the
// screen can be compared with the hand-made davinci2.

const v = "v0.9" as const
const URGENCY: Record<Urgency, string> = {
  now: "Now",
  today: "Today",
  later: "Can wait",
}

const ev = (name: string, context?: Record<string, unknown>) => ({
  event: { name, ...(context ? { context } : {}) },
})
const bind = (id: string, key: string) => ({ path: `/items/${id}/${key}` })

function card(q: QueueItem): ComponentNode {
  const common = {
    id: q.id,
    eyebrow: bind(q.id, "eyebrow"),
    title: bind(q.id, "title"),
  }
  const actions =
    q.kind === "incident"
      ? [
          { label: "Revert 3f2a1c", action: ev("revert", { id: q.id }) },
          {
            label: "Keep and investigate",
            kind: "secondary",
            action: ev("keep", { id: q.id }),
          },
        ]
      : q.kind === "diff"
        ? [
            { label: "Approve", action: ev("integrate", { id: q.id }) },
            {
              label: "Return with note",
              kind: "secondary",
              action: ev("return", { id: q.id }),
            },
            {
              label: "See the diff",
              kind: "aside",
              action: ev("open_diff", { id: q.id }),
            },
          ]
        : q.kind === "preview"
          ? [
              { label: "Promote", action: ev("promote", { id: q.id }) },
              {
                label: "Adjust",
                kind: "secondary",
                action: ev("adjust", { id: q.id }),
              },
              {
                label: "Before / after",
                kind: "aside",
                action: ev("open_preview", { id: q.id }),
              },
            ]
          : undefined
  return {
    ...common,
    component: "DecisionCard",
    agent: "davinci",
    context: bind(q.id, "context"),
    consequence: bind(q.id, "consequence"),
    urgent: q.urgency === "now",
    ...(q.kind === "choice"
      ? {
          options: bind(q.id, "options"),
          pick: bind(q.id, "pick"),
          chooseAction: ev("choose", { id: q.id }),
        }
      : {}),
    ...(actions ? { actions } : {}),
    ...(q.agreement ? { agreement: bind(q.id, "agreement") } : {}),
  }
}

export function composeInbox(
  open: QueueItem[],
  answeredCount: number
): SurfaceMessage[] {
  const nodes: ComponentNode[] = [
    {
      id: "header",
      component: "Column",
      gap: "sm",
      children: ["title", "since"],
    },
    {
      id: "title",
      component: "Text",
      variant: "title",
      text: { path: "/summary/title" },
    },
    {
      id: "since",
      component: "Text",
      variant: "muted",
      text: { path: "/summary/since" },
    },
  ]
  const sections: string[] = ["header"]
  for (const u of ["now", "today", "later"] as Urgency[]) {
    const items = open.filter((q) => q.urgency === u)
    if (!items.length) continue
    nodes.push(
      {
        id: `group-${u}`,
        component: "Column",
        gap: "sm",
        children: [`label-${u}`, ...items.map((q) => q.id)],
      },
      {
        id: `label-${u}`,
        component: "Text",
        variant: "eyebrow",
        text: URGENCY[u],
      },
      ...items.map(card)
    )
    sections.push(`group-${u}`)
  }
  if (answeredCount) {
    nodes.push(
      {
        id: "answered",
        component: "List",
        title: "Answered today",
        children: { path: "/answered", componentId: "answeredRow", key: "id" },
      },
      {
        id: "answeredRow",
        component: "KeyValue",
        label: { path: "what" },
        value: { path: "project" },
      }
    )
    sections.push("answered")
  }
  nodes.unshift({
    id: "root",
    component: "Column",
    gap: "lg",
    children: sections,
  })
  return [
    {
      version: v,
      createSurface: { surfaceId: "inbox", catalogId: UIA_CATALOG_ID },
    },
    { version: v, updateComponents: { surfaceId: "inbox", components: nodes } },
  ]
}

/** "Decided for you": the agent's own decisions, each undoable by the host's rules. */
export function composeDecided(): SurfaceMessage[] {
  return [
    {
      version: v,
      createSurface: { surfaceId: "decided", catalogId: UIA_CATALOG_ID },
    },
    {
      version: v,
      updateComponents: {
        surfaceId: "decided",
        components: [
          {
            id: "root",
            component: "Column",
            gap: "sm",
            children: ["title", "log"],
          },
          {
            id: "title",
            component: "Text",
            variant: "title",
            text: "Decided for you",
          },
          {
            id: "log",
            component: "ActivityList",
            children: { path: "/decided", componentId: "entry", key: "id" },
          },
          {
            id: "entry",
            component: "ActivityItem",
            time: { path: "time" },
            subject: { path: "subject" },
            what: { path: "what" },
            why: { path: "why" },
            rule: { path: "rule" },
            undone: { path: "undone" },
            undoAction: ev("undo", { id: { path: "id" } }),
          },
        ],
      },
    },
  ]
}

/** Rules: standing policies the person can switch off. */
export function composeRules(): SurfaceMessage[] {
  return [
    {
      version: v,
      createSurface: { surfaceId: "rules", catalogId: UIA_CATALOG_ID },
    },
    {
      version: v,
      updateComponents: {
        surfaceId: "rules",
        components: [
          {
            id: "root",
            component: "Column",
            gap: "sm",
            children: ["title", "list"],
          },
          { id: "title", component: "Text", variant: "title", text: "Rules" },
          {
            id: "list",
            component: "PolicyList",
            children: { path: "/rules", componentId: "rule", key: "id" },
          },
          {
            id: "rule",
            component: "Policy",
            text: { path: "text" },
            category: { path: "category" },
            applied: { path: "applied" },
            on: { path: "on" },
            toggleAction: ev("toggle_rule", { id: { path: "id" } }),
          },
        ],
      },
    },
  ]
}

import * as React from "react"
import { CodeIcon, TriangleAlertIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Segmented, SegmentedItem } from "@/components/ds/segmented"
import { ResolvedRow } from "@/components/parts/action-card"
import { Surface } from "@/components/surface/surface"
import { surfaceFromMessages } from "@/components/surface/store"
import type { SurfaceIssue, SurfaceMessage } from "@/components/surface/types"
import { uiaCatalog } from "@/components/catalog"
import {
  composeDecided,
  composeInbox,
  composeRules,
} from "@/examples/davinci-surface/compose"
import {
  factoryActions,
  factoryData,
  QUEUE,
} from "@/examples/davinci-surface/factory"

// davinci on surfaces: the same inbox as the hand-made davinci2, but every
// screen is A2UI messages an agent sends (compose.ts), bound to the
// factory's data (factory.ts) and rendered by <Surface> with the factory's
// action contract. Answering runs the host's action and the agent's screen
// updates from the data. Compare with /davinci2.

type View = "inbox" | "decided" | "rules"

const ANSWER_LABEL: Record<string, string> = {
  revert: "Reverted 3f2a1c",
  keep: "Kept v12",
  integrate: "Approved",
  return: "Returned",
  promote: "Promoted",
  adjust: "Sent back",
  choose: "Answered",
}

export function DavinciSurfaceExample() {
  const [view, setView] = React.useState<View>("inbox")
  const [answered, setAnswered] = React.useState<Record<string, string>>({})
  const [rulesOff, setRulesOff] = React.useState<Record<string, boolean>>({})
  const [panel, setPanel] = React.useState<string | null>(null)
  const [issues, setIssues] = React.useState<SurfaceIssue[]>([])
  const [showSpec, setShowSpec] = React.useState(false)

  const data = React.useMemo(() => {
    const d = factoryData(answered)
    return { ...d, rules: d.rules.map((r) => ({ ...r, on: !rulesOff[r.id] })) }
  }, [answered, rulesOff])

  const open = QUEUE.filter((q) => !answered[q.id])
  const components: SurfaceMessage[] =
    view === "inbox"
      ? composeInbox(
          open,
          Object.keys(answered).filter((k) => !k.startsWith("undo:")).length
        )
      : view === "decided"
        ? composeDecided()
        : composeRules()
  const surfaceId = view === "inbox" ? "inbox" : view
  const messages: SurfaceMessage[] = [
    ...components,
    { version: "v0.9", updateDataModel: { surfaceId, path: "/", value: data } },
  ]

  return (
    <div className="mx-auto flex w-full max-w-[44rem] flex-col gap-6 px-4 pt-8 pb-28 sm:px-6">
      <div className="flex flex-wrap items-center gap-3">
        <Segmented
          variant="sans"
          value={view}
          onValueChange={(v) => {
            setView(v as View)
            setIssues([])
          }}
        >
          <SegmentedItem value="inbox">Inbox</SegmentedItem>
          <SegmentedItem value="decided">Decided for you</SegmentedItem>
          <SegmentedItem value="rules">Rules</SegmentedItem>
        </Segmented>
        <Button
          size="sm"
          variant="ghost"
          className="ml-auto text-muted-foreground"
          aria-pressed={showSpec}
          onClick={() => setShowSpec((s) => !s)}
        >
          <CodeIcon />
          {showSpec ? "Hide spec" : "Spec"}
        </Button>
      </div>

      <Surface
        key={view}
        surface={surfaceFromMessages(messages)}
        catalog={uiaCatalog}
        actions={factoryActions}
        showIssues
        onIssue={(i) => setIssues((all) => [...all, i])}
        onAction={(a) => {
          const id = String(a.context.id ?? "")
          if (a.name === "open_diff" || a.name === "open_preview")
            return setPanel(`${a.name} · ${id}`)
          if (a.name === "undo")
            return setAnswered((s) => ({ ...s, [`undo:${id}`]: "Undone" }))
          if (a.name === "toggle_rule")
            return setRulesOff((s) => ({ ...s, [id]: a.context.on === false }))
          if (a.name === "make_rule") return
          const label =
            a.name === "choose"
              ? String(a.context.option ?? "Answered")
              : (ANSWER_LABEL[a.name] ?? a.name)
          setAnswered((s) => ({ ...s, [id]: label }))
        }}
      />

      {panel && (
        <ResolvedRow
          icon={<CodeIcon />}
          label="Would open the side panel"
          summary={panel}
        />
      )}

      {issues.length > 0 && (
        <div className="flex flex-col gap-1.5">
          {issues.map((i, n) => (
            <ResolvedRow
              key={n}
              icon={<TriangleAlertIcon />}
              label={`${i.code} · ${i.componentId}`}
              summary={i.message}
              muted
            />
          ))}
        </div>
      )}

      {showSpec && (
        <pre className="max-h-[28rem] overflow-auto rounded-2xl bg-muted/50 p-4 font-mono text-xs leading-relaxed text-muted-foreground">
          {JSON.stringify(components, null, 2)}
        </pre>
      )}
    </div>
  )
}
